// Decisions from evidence for Owner › Official videos (server/videos/videoDecisions.ts applies them at boot): each
// video in the owner's review queue or among the channel audit's findings, decided by checking the video itself.
// link: a real FTC recording of exactly that event, day and part. reject: not FTC (FRC, FLL, FGC, a simulator, a
// meeting, a webinar). setAside: FTC, but not a day's recording Scout can play (a clip, unplayable, a second copy, two
// events in one video, no Scout event to put it on). Every entry carries the line of evidence it rests on. Decided
// 2026-11-16 from the live queue (69) and the audit's open findings (323); a later decision is a new entry.
export interface VideoDecision {
  videoId: string;
  decision: "link" | "reject" | "setAside";
  /** A link's event and the venue-local day it covers; part only when the video's own title names it. */
  season?: number; code?: string; day?: string; part?: string | null;
  /** A link may take the day of a video YouTube no longer plays (deleted or private), which comes off the event. */
  replaces?: string;
  /** For reject and set aside: the specific reason, shown to the owner. */
  reason?: string;
  /** What was checked: title, description, broadcast date against the event's days, length, frames. */
  evidence: string;
}

